// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address addr, uint256 callerSeed) public {
        address priorCaller = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed, "prior")))));

        vm.deal(priorCaller, 1 ether);

        vm.startPrank(priorCaller);
        c.SetMinSum(123);
        vm.stopPrank();

        bool ok;
        try c.SetLogFile(addr) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
